class Solution {
public:
    bool stoneGameIX(vector<int>& stones) {
        long c[3] = {0, 0, 0};
        for (int x : stones) c[x % 3]++;
        if (c[0] % 2 == 0) return c[1] >= 1 && c[2] >= 1;
        long d = c[1] > c[2] ? c[1] - c[2] : c[2] - c[1];
        return d > 2;
    }
};
